import { Geo, boxGeo, cylGeo, loftGeo, transformGeo, mergeGeo, buildGLB } from './glb.js';

function sportsCar(color = [0.9, 0.2, 0.2]) {
  const body = loftGeo([
    { z: -2.2, w: 0.85, y0: 0.2, y1: 0.55 },
    { z: -1.5, w: 0.9, y0: 0.15, y1: 0.65 },
    { z: -0.5, w: 0.92, y0: 0.1, y1: 0.8 },
    { z: 0.5, w: 0.9, y0: 0.1, y1: 0.75 },
    { z: 1.5, w: 0.85, y0: 0.15, y1: 0.6 },
    { z: 2.0, w: 0.8, y0: 0.2, y1: 0.5 },
  ]);
  const glass = loftGeo([
    { z: -0.8, w: 0.7, y0: 0.7, y1: 1.0 },
    { z: -0.3, w: 0.75, y0: 0.75, y1: 1.05 },
    { z: 0.5, w: 0.72, y0: 0.7, y1: 0.95 },
  ]);
  const wheelFL = cylGeo(0.3, 0.3, 0.25, 16);
  const wFL = transformGeo(wheelFL, { t: [-0.7, 0.3, -1.3], r: [0, 0, Math.PI / 2] });
  const wFR = transformGeo(wheelFL, { t: [0.7, 0.3, -1.3], r: [0, 0, Math.PI / 2] });
  const wRL = transformGeo(wheelFL, { t: [-0.7, 0.3, 1.3], r: [0, 0, Math.PI / 2] });
  const wRR = transformGeo(wheelFL, { t: [0.7, 0.3, 1.3], r: [0, 0, Math.PI / 2] });
  const spoiler = boxGeo(1.6, 0.08, 0.3, 0, 0.85, 1.8);
  const headlightL = boxGeo(0.2, 0.15, 0.1, -0.5, 0.4, -2.25);
  const headlightR = boxGeo(0.2, 0.15, 0.1, 0.5, 0.4, -2.25);
  return {
    nodes: [
      { name: 'body', geo: body, material: { color, metal: 0.7, rough: 0.3 } },
      { name: 'glass', geo: glass, material: { color: [0.1, 0.1, 0.15], metal: 0.1, rough: 0.1, alpha: 0.4 } },
      { name: 'wheelFL', geo: wFL, material: { color: [0.15, 0.15, 0.15], rough: 0.8 } },
      { name: 'wheelFR', geo: wFR, material: { color: [0.15, 0.15, 0.15], rough: 0.8 } },
      { name: 'wheelRL', geo: wRL, material: { color: [0.15, 0.15, 0.15], rough: 0.8 } },
      { name: 'wheelRR', geo: wRR, material: { color: [0.15, 0.15, 0.15], rough: 0.8 } },
      { name: 'spoiler', geo: spoiler, material: { color: [0.1, 0.1, 0.1], metal: 0.5, rough: 0.5 } },
      { name: 'headlightL', geo: headlightL, material: { color: [1, 1, 0.9], emissive: [1, 1, 0.8] } },
      { name: 'headlightR', geo: headlightR, material: { color: [1, 1, 0.9], emissive: [1, 1, 0.8] } },
    ],
  };
}

function policeCar() {
  const car = sportsCar([0.1, 0.1, 0.95]);
  const lightbar = boxGeo(1.2, 0.15, 0.2, 0, 1.05, -0.2);
  const lightL = boxGeo(0.25, 0.12, 0.15, -0.4, 1.1, -0.2);
  const lightR = boxGeo(0.25, 0.12, 0.15, 0.4, 1.1, -0.2);
  car.nodes.push(
    { name: 'lightbar', geo: lightbar, material: { color: [0.2, 0.2, 0.2], metal: 0.3, rough: 0.5 } },
    { name: 'lightL', geo: lightL, material: { color: [1, 0, 0], emissive: [2, 0, 0] } },
    { name: 'lightR', geo: lightR, material: { color: [0, 0, 1], emissive: [0, 0, 2] } },
  );
  return car;
}

function trafficSedan() {
  const body = loftGeo([
    { z: -2.0, w: 0.8, y0: 0.25, y1: 0.6 },
    { z: -1.2, w: 0.85, y0: 0.2, y1: 0.9 },
    { z: 0, w: 0.85, y0: 0.2, y1: 0.95 },
    { z: 1.2, w: 0.82, y0: 0.2, y1: 0.85 },
    { z: 2.0, w: 0.78, y0: 0.25, y1: 0.6 },
  ]);
  const glass = loftGeo([
    { z: -1.0, w: 0.65, y0: 0.8, y1: 1.2 },
    { z: 0, w: 0.68, y0: 0.85, y1: 1.25 },
    { z: 1.0, w: 0.62, y0: 0.78, y1: 1.15 },
  ]);
  const wheel = cylGeo(0.28, 0.28, 0.22, 12);
  const wFL = transformGeo(wheel, { t: [-0.65, 0.28, -1.2], r: [0, 0, Math.PI / 2] });
  const wFR = transformGeo(wheel, { t: [0.65, 0.28, -1.2], r: [0, 0, Math.PI / 2] });
  const wRL = transformGeo(wheel, { t: [-0.65, 0.28, 1.2], r: [0, 0, Math.PI / 2] });
  const wRR = transformGeo(wheel, { t: [0.65, 0.28, 1.2], r: [0, 0, Math.PI / 2] });
  return {
    nodes: [
      { name: 'body', geo: body, material: { color: [0.7, 0.7, 0.7], metal: 0.5, rough: 0.4 } },
      { name: 'glass', geo: glass, material: { color: [0.15, 0.15, 0.2], metal: 0.1, rough: 0.1, alpha: 0.5 } },
      { name: 'wheelFL', geo: wFL, material: { color: [0.1, 0.1, 0.1], rough: 0.9 } },
      { name: 'wheelFR', geo: wFR, material: { color: [0.1, 0.1, 0.1], rough: 0.9 } },
      { name: 'wheelRL', geo: wRL, material: { color: [0.1, 0.1, 0.1], rough: 0.9 } },
      { name: 'wheelRR', geo: wRR, material: { color: [0.1, 0.1, 0.1], rough: 0.9 } },
    ],
  };
}

function neonSign(text = 'NEON') {
  const base = boxGeo(3, 0.1, 1.5, 0, 4, 0);
  const letters = [];
  for (let i = 0; i < text.length; i++) {
    const l = boxGeo(0.4, 0.8, 0.05, (i - text.length / 2) * 0.5, 4.2, 0.08);
    letters.push(l);
  }
  const pole = cylGeo(0.08, 0.08, 4, 8);
  const pL = transformGeo(pole, { t: [-1.4, 2, 0] });
  const pR = transformGeo(pole, { t: [1.4, 2, 0] });
  return {
    nodes: [
      { name: 'base', geo: base, material: { color: [0.1, 0.1, 0.1], metal: 0.8, rough: 0.3 } },
      ...letters.map((l, i) => ({ name: `letter${i}`, geo: l, material: { color: [1, 0.2, 1], emissive: [3, 0.5, 3] } })),
      { name: 'poleL', geo: pL, material: { color: [0.2, 0.2, 0.2], metal: 0.7, rough: 0.4 } },
      { name: 'poleR', geo: pR, material: { color: [0.2, 0.2, 0.2], metal: 0.7, rough: 0.4 } },
    ],
  };
}

function barrier() {
  const posts = [];
  for (let i = 0; i < 5; i++) {
    const p = cylGeo(0.05, 0.05, 1, 8);
    posts.push(transformGeo(p, { t: [0, 0.5, i * 1.5 - 3] }));
  }
  const rail = boxGeo(0.08, 0.15, 7, 0, 0.9, 0);
  return {
    nodes: [
      ...posts.map((p, i) => ({ name: `post${i}`, geo: p, material: { color: [0.8, 0.8, 0.8], metal: 0.6, rough: 0.4 } })),
      { name: 'rail', geo: rail, material: { color: [0.9, 0.9, 0.2], metal: 0.5, rough: 0.5 } },
    ],
  };
}

function roadSegment() {
  const g = new Geo();
  const w = 10, l = 20;
  g.quad([-w / 2, 0, -l / 2], [w / 2, 0, -l / 2], [w / 2, 0, l / 2], [-w / 2, 0, l / 2], [0, 1, 0]);
  return {
    nodes: [
      { name: 'road', geo: g, material: { color: [0.15, 0.15, 0.18], rough: 0.9 } },
    ],
  };
}

// Generate all models
const models = [
  { name: 'car_red', spec: sportsCar([0.9, 0.2, 0.2]) },
  { name: 'car_blue', spec: sportsCar([0.2, 0.3, 0.95]) },
  { name: 'car_green', spec: sportsCar([0.2, 0.85, 0.3]) },
  { name: 'car_yellow', spec: sportsCar([0.95, 0.85, 0.2]) },
  { name: 'car_purple', spec: sportsCar([0.7, 0.2, 0.9]) },
  { name: 'car_orange', spec: sportsCar([0.95, 0.5, 0.1]) },
  { name: 'police', spec: policeCar() },
  { name: 'traffic_sedan', spec: trafficSedan() },
  { name: 'neon_sign', spec: neonSign('SPEED') },
  { name: 'barrier', spec: barrier() },
  { name: 'road_segment', spec: roadSegment() },
];

for (const m of models) {
  const path = `public/models/${m.name}.glb`;
  const r = buildGLB(path, { ...m.spec, name: m.name });
  console.log(`✓ ${m.name}: ${(r.bytes / 1024).toFixed(1)}KB, ${r.tris} tris`);
}

